      "anno": 1901,
      "data_rilevamento": "10 feb",
      "popolazione_residente": 10808,
      "variazione_percentuale": 5.1,
      "note_storiche": "La data di riferimento del censimento viene spostata a febbraio. Vengono introdotte schede individuali per ogni componente della famiglia."
